    37	static void change_u16_endianness(uint8_t *dst, const uint8_t *src, unsigned size, unsigned be)
    38	{
    39	        unsigned convert = 0;
    40	        unsigned i;
    41	        uint8_t tmp;
    42	
    43	#ifdef WORDS_BIGENDIAN
    44	        if (!be)
    45	                convert = 1;
    46	#else
    47	        if (be)
    48	                convert = 1;
    49	#endif
    50	
    51	        /* convert to LE */
    52	        if (convert) {
    53	                for (i = 0; i < size; i += 2) {
    54	                        tmp = src[i];
    55	                        dst[i] = src[1 + i];
    56	                        dst[1 + i] = tmp;
    57	                }
    58	        } else {
    59	                if (dst != src)
    60	                        memcpy(dst, src, size);
    61	        }
    62	}
    63	
    64	int _gnutls_ucs2_to_utf8(const void *data, size_t size,
    65	                         gnutls_datum_t * output, unsigned be)
    66	{
    67	        int ret;
    68	        size_t dstlen;
    69	        void *src;
    70	        uint8_t *tmp_dst = NULL;
    71	        uint8_t *dst = NULL;
    72	
    73	        if (size > 2 && ((uint8_t *) data)[size-1] == 0 && ((uint8_t *) data)[size-2] == 0) {
    74	                size -= 2;
    75	        }
    76	
    77	        if (size == 0)
    78	                return gnutls_assert_val(GNUTLS_E_INVALID_REQUEST);
    79	
    80	        src = gnutls_malloc(size+2);
    81	        if (src == NULL)
    82	                return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
    83	
    84	        /* convert to LE if needed */
    85	        change_u16_endianness(src, data, size, be);
    86	
    87	        dstlen = 0;
    88	        tmp_dst = u16_to_u8((uint16_t*)src, size/2, NULL, &dstlen);
    89	        if (tmp_dst == NULL) {
    90	                ret = gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
    91	                goto fail;
    92	        }
    93	
    94	        dst = gnutls_malloc(dstlen+1);
    95	        if (dst == NULL) {
    96	                gnutls_assert();
    97	                ret = GNUTLS_E_MEMORY_ERROR;
    98	                goto fail;
    99	        }
   100	
   101	        memcpy(dst, tmp_dst, dstlen);
   102	        dst[dstlen] = 0;
   103	
   104	        output->data = (void *) dst;
   105	        output->size = dstlen;
   106	
   107	        ret = 0;
   108	        goto cleanup;
   109	
   110	 fail:
   111	        gnutls_free(dst);
   112	
   113	 cleanup:
   114	        gnutls_free(src);
   115	        free(tmp_dst);
   116	
   117	        return ret;
   118	}
