   120	/* This is big-endian output only */
   121	int _gnutls_utf8_to_ucs2(const void *data, size_t size,
   122	                         gnutls_datum_t * output)
   123	{
   124	        int ret;
   125	        size_t dstlen, nrm_size = 0, tmp_size = 0;
   126	        uint16_t *tmp_dst = NULL;
   127	        uint16_t *nrm_dst = NULL;
   128	        uint8_t *dst = NULL;
   129	
   130	        if (size == 0)
   131	                return gnutls_assert_val(GNUTLS_E_INVALID_REQUEST);
   132	
   133	        tmp_dst = u8_to_u16(data, size, NULL, &tmp_size);
   134	        if (tmp_dst == NULL)
   135	                return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
   136	
   137	        nrm_dst = u16_normalize(UNINORM_NFC, tmp_dst, tmp_size, NULL, &nrm_size);
   138	        if (nrm_dst == NULL) {
   139	                ret = gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
   140	                goto fail;
   141	        }
   142	
   143	        dstlen = nrm_size * 2; /* convert to bytes */
   144	
   145	        dst = gnutls_malloc(dstlen+2);
   146	        if (dst == NULL) {
   147	                gnutls_assert();
   148	                ret = GNUTLS_E_MEMORY_ERROR;
   149	                goto fail;
   150	        }
   151	
   152	        /* convert to BE */
   153	        change_u16_endianness(dst, (uint8_t*)tmp_dst, dstlen, 1);
   154	        dst[dstlen] = 0;
   155	        dst[dstlen+1] = 0;
   156	
   157	        output->data = (void *) dst;
   158	        output->size = dstlen;
   159	
   160	        ret = 0;
   161	        goto cleanup;
   162	
   163	 fail:
   164	        gnutls_free(dst);
   165	
   166	 cleanup:
   167	        free(tmp_dst);
   168	        free(nrm_dst);
   169	
   170	        return ret;
   171	}
